private final Map<String, SseEmitter> streams = new ConcurrentHashMap<>();

@GetMapping("/api/events")
public SseEmitter subscribe(@RequestParam String userId) {
    SseEmitter emitter = new SseEmitter(0L);
    streams.put(userId, emitter);
    return emitter;
}

// called by the order service, in this JVM
public void onOrderPaid(String userId, String payload) throws IOException {
    SseEmitter emitter = streams.get(userId);
    if (emitter != null) {
        emitter.send(payload);
    }
}
